import {
  isProgramError,
  type Address,
  type HasAddress,
  type SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM,
  type SolanaError,
} from "@solana/kit";
import { MAKER_B_PROGRAM_ADDRESS } from "../programs/index.js";

/** Authority: Wrong maker config authority */
export const MAKER_B_ERROR__AUTHORITY = 0x1770; // 6000
/** Binding: Invalid maker binding */
export const MAKER_B_ERROR__BINDING = 0x1771; // 6001
/** Lifetime: Epoch lifetime invalid or previous epoch still active */
export const MAKER_B_ERROR__LIFETIME = 0x1772; // 6002
/** Quote: Quote outside bounded strategy, capacity or lifetime */
export const MAKER_B_ERROR__QUOTE = 0x1773; // 6003

export type MakerBError =
  | typeof MAKER_B_ERROR__AUTHORITY
  | typeof MAKER_B_ERROR__BINDING
  | typeof MAKER_B_ERROR__LIFETIME
  | typeof MAKER_B_ERROR__QUOTE;

let makerBErrorMessages: Record<MakerBError, string> | undefined;
if (process.env["NODE_ENV"] !== "production") {
  makerBErrorMessages = {
    [MAKER_B_ERROR__AUTHORITY]: `Wrong maker config authority`,
    [MAKER_B_ERROR__BINDING]: `Invalid maker binding`,
    [MAKER_B_ERROR__LIFETIME]: `Epoch lifetime invalid or previous epoch still active`,
    [MAKER_B_ERROR__QUOTE]: `Quote outside bounded strategy, capacity or lifetime`,
  };
}

export function getMakerBErrorMessage(code: MakerBError): string {
  if (process.env["NODE_ENV"] !== "production") {
    return (makerBErrorMessages as Record<MakerBError, string>)[code];
  }

  return "Error message not available in production bundles.";
}

export function isMakerBError<TProgramErrorCode extends MakerBError>(
  error: unknown,
  transactionMessage: {
    instructions: Record<number, { programAddress: Address }>;
  },
  code?: TProgramErrorCode,
  config: { programAddress?: Address | HasAddress } = {},
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  const programAddressInput = config.programAddress ?? MAKER_B_PROGRAM_ADDRESS;
  const programAddress =
    typeof programAddressInput === "string"
      ? programAddressInput
      : programAddressInput.address;
  return isProgramError<TProgramErrorCode>(
    error,
    transactionMessage,
    programAddress,
    code,
  );
}
